#!/usr/bin/env node
// Generates registry/proto-lab/examples/index.ts from the example files, so a
// new example only needs its own file. Runs before dev and build.
import fs from "node:fs"
import path from "node:path"

const dir = path.join(import.meta.dirname, "..", "registry", "proto-lab", "examples")
const names = fs.readdirSync(dir).filter((f) => f.endsWith(".tsx")).map((f) => f.slice(0, -4)).sort()
const ident = (n) => n.split("-").map((w) => w[0].toUpperCase() + w.slice(1)).join("")
const out = [
  "// GENERATED by scripts/examples-index.mjs from the files in this folder. Do not edit.",
  'import type { ComponentType } from "react"',
  "",
  ...names.map((n) => `import ${ident(n)} from "./${n}"`),
  "",
  "export const examples: Record<string, ComponentType> = {",
  ...names.map((n) => `  "${n}": ${ident(n)},`),
  "}",
  "",
].join("\n")
const file = path.join(dir, "index.ts")
const check = process.argv.includes("--check")
const prev = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : null
if (prev === out) process.exit(0)
if (check) { console.error("examples/index.ts is stale. Run `node scripts/examples-index.mjs`."); process.exit(1) }
fs.writeFileSync(file, out)
console.log(`examples/index.ts: ${names.length} examples`)
